d=pd.read_csv('data/top10-songs.csv')
periods=[(1958.5,1969),(1970,1979),(1980,1989),(1990,1999),(2000,2009),(2010,2019),(2020,2024)]
for lo,hi in periods:
    x=d[(d.date_as_decimal>=lo)&(d.date_as_decimal<hi)]
    def sh(types): return round(100*x.loc[x.love_song_sub_type.isin(types),'total_weeks_in_top_10'].sum()/x.total_weeks_in_top_10.sum(),2)
